Ext.define('GridHTML.view.GaugeUtils', {
    extend: 'Ext.Base',

    renderGauge: function(component) {

        var ids = component.store.gaugeIds,
            store = component.store,
            items = store.visualizationsCfg,
            length = items.length,
            i = 0,
            temp,
            zones,
            semaphore,
            gauge,
            j,
            config;

        for (; i < length; i++) {

            j = items[i];
            if (j.type === "velocimeter") {
                zones = undefined;

                if (j.cfg !== undefined) {
                    temp = {
                        size: 44.4,
                        minorTicks: 1,
                        majorTicks: 2,
                        min: j.min,
                        max: j.max
                    };

                    temp.blueZones = j.cfg.blue || [];
                    temp.redZones = j.cfg.red || [];
                    temp.yellowZones = j.cfg.yellow || [];
                    temp.greenZones = j.cfg.green || [];

                    gauge = new Gauge(ids[i], temp);
                    gauge.render();
                    gauge.redraw(j.value);

                } else {
                    temp = {
                        size: 44.4,
                        minorTicks: 1,
                        majorTicks: 2,
                        blueZones: [],
                        redZones: [],
                        yellowZones: [],
                        greenZones: []
                    };
                    gauge = new Gauge(ids[i], temp);
                    gauge.render();
                }
            } else if (j.type === "semaphore") {
                config = {
                    backgroundColor: j.cfg.backgroundColor,
                    image: j.cfg.image,
                    size: 40
                };
                semaphore = new Semaphore(ids[i], config);
                semaphore.render();

            }

        }

    }

});